// Ziel für einen Beleg berechnen, der nicht automatisch gebucht wird (Vorgabe Stefan, 14.10.2026):
// manuell  -> PDF in den Ordner _Manuell-zu-bearbeiten (Bereich Buchhaltung), Beleg-Status manuell
// duplikat -> PDF zu den aussortierten Belegen (Belege-Irrelevant, Bereich Ally-Dateien), Beleg-Status duplikat
// Verschoben wird über SPEICHER 1 (Server oder eigener Speicherort). Testläufe verschieben nichts und schreiben nichts.
// Als Unterablauf läuft BELEG 3 im Modus integrated, deshalb entscheidet das Eingabefeld test des Aufrufers (bzw. ein direkter Testlauf mit mode test).
const e = $('1.1 Start').item.json;
const b = $input.item.json || {};
const test = e.test === true || e.test === 'true' || $execution.mode === 'test';

if (!b.id) throw new Error('Beleg ' + e.beleg_id + ' wurde nicht gefunden.');
if (!['manuell', 'duplikat'].includes(e.ziel)) throw new Error('Unbekanntes Ziel „' + e.ziel + '“ (erlaubt: manuell, duplikat).');
if (b.processing_status === 'verarbeitet') throw new Error('Beleg ' + b.id + ' ist bereits gebucht und wird nicht verschoben.');

const STAGING = 'Belegerfassung/Belege-Staging/';
const bereich = b.datei_bereich || '';
const pfad = b.datei_pfad || '';
const imStaging = bereich === 'ally' && pfad.startsWith(STAGING) && pfad.length > STAGING.length;
const name = (pfad.split('/').pop() || ('beleg-' + b.id + '.pdf')).replace(/[^A-Za-z0-9._-]/g, '_');
const dupVon = Number(e.duplikat_von) || 0;

const ziel = e.ziel === 'manuell'
  ? { bereich: 'buchhaltung', pfad: '_Manuell-zu-bearbeiten/Beleg-' + b.id + '_' + name }
  : { bereich: 'ally', pfad: 'Belegerfassung/Belege-Irrelevant/' + (dupVon ? 'Duplikat-zu-Beleg-' + dupVon + '_' : 'Duplikat-Beleg-' + b.id + '_') + name };

const verschieben = !test && imStaging;
const neu = verschieben ? ziel : { bereich, pfad };

return {
  json: {
    beleg_id: b.id,
    ziel: e.ziel,
    grund: e.grund || '',
    melden: e.melden === true || e.melden === 'true',
    duplikat_von: dupVon || null,
    antwort_text: e.antwort_text || '',
    test,
    alter_bereich: bereich,
    alter_pfad: pfad,
    im_staging: imStaging,
    ziel_bereich: ziel.bereich,
    ziel_pfad: ziel.pfad,
    verschieben,
    neuer_bereich: neu.bereich,
    neuer_pfad: neu.pfad,
    // Auftrag an SPEICHER 1 (nur genutzt, wenn verschoben wird)
    aktion: 'verschieben', bereich, pfad, ueberschreiben: true,
    beleg: b
  }
};

// Kurze Info an alle mit eingeschalteten Klärungsnachrichten. Chat-Layout (Vorgabe Stefan, 11.10.2026):
// Titel fett mit Doppelpunkt, Inhalt direkt darunter, Leerzeile zwischen Blöcken, keine Listenpunkte, keine Emojis
// Die PDF geht als eigene Nachricht direkt nach dem Text in den Chat (Chat-Bot, Feld datei), kein Link mehr.
const d = $('1.3 Ziel berechnen').item.json;
const b = d.beleg || {};
const esc = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '').split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
const roh = v => String(v ?? '').replace(/[\p{Extended_Pictographic}️‍]/gu, '');
const zeileHtml = z => typeof z === 'string' ? esc(z) : (z.html !== undefined ? z.html : esc(z.t));
const zeileText = z => typeof z === 'string' ? roh(z) : roh(z.t);
const render = bloecke => {
  const x = bloecke.filter(y => y && (y.titel || (y.zeilen || []).length));
  return {
    html: x.map(y => (y.titel ? '<strong>' + esc(y.titel) + '</strong>' + ((y.zeilen || []).length ? '<br>' : '') : '') + (y.zeilen || []).map(zeileHtml).join('<br>')).join('<br><br>'),
    text: x.map(y => (y.titel ? roh(y.titel) + ((y.zeilen || []).length ? '\n' : '') : '') + (y.zeilen || []).map(zeileText).join('\n')).join('\n\n')
  };
};
const w = v => (v === null || v === undefined || v === '') ? '-' : String(v);
const statusText = { verarbeitet: 'gebucht', klaerung_offen: 'Klärung offen', neu: 'in Bearbeitung', manuell: 'zur Handarbeit', fehler: 'Fehler', klaerung_erledigt: 'Klärung erledigt' };

// PDF aus SPEICHER 1 (Eingang dieses Knotens)
const h = $input.item.json || {};
let datei = null;
if (h.ok === true && $input.item.binary && $input.item.binary.datei) {
  try {
    const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'datei');
    if (buf.length > 0 && buf.length <= 10 * 1024 * 1024) datei = { name: String(d.neuer_pfad || '').split('/').pop() || ('Beleg-' + d.beleg_id + '.pdf'), mimetype: $input.item.binary.datei.mimeType || 'application/pdf', data_base64: buf.toString('base64') };
  } catch (e) { datei = null; }
}

const bloecke = [];
if (d.ziel === 'duplikat') {
  bloecke.push({ titel: 'Beleg als Duplikat abgelegt.' });
  bloecke.push({ titel: 'Grund:', zeilen: [d.grund || ('Diese Rechnung ist schon als Beleg ' + w(d.duplikat_von) + ' erfasst. Sie wird nicht noch einmal gebucht.')] });
  if (b.dup_id) bloecke.push({ titel: 'Schon erfasst als:', zeilen: [
    'Beleg ' + b.dup_id + ' (' + (statusText[b.dup_status] || w(b.dup_status)) + ')',
    'Rechnungsnummer: ' + w(b.dup_rechnungsnummer)
  ] });
} else {
  bloecke.push({ titel: 'Beleg muss von Hand gebucht werden.' });
  bloecke.push({ titel: 'Grund:', zeilen: [d.grund || 'Der Beleg kann nicht automatisch gebucht werden.'] });
}
bloecke.push({ titel: 'Beleg:', zeilen: [
  'Von: ' + w(b.sender),
  'Betreff: ' + w(b.subject),
  'Lieferant: ' + w(b.creditor_name_extrahiert),
  'Rechnungsnummer: ' + w(b.rechnungsnummer),
  'Betrag brutto: ' + (b.betrag == null ? '-' : b.betrag + ' EUR')
] });
// Produktname aus der Datenbank (1.2 Beleg laden) statt fest im Code (Stefan 18.10.2026)
const produkt = String(b.produkt_name || '').trim();
if (d.neuer_pfad) {
  const ort = h.ort || 'Speicherort';
  bloecke.push({ titel: 'PDF:', zeilen: [
    datei ? 'kommt direkt nach dieser Nachricht.' : 'konnte nicht angehängt werden' + (h.fehler ? ' (' + h.fehler + ')' : '') + '.',
    'Ablage (' + ort + ', ' + (d.neuer_bereich === 'buchhaltung' ? 'Buchhaltung' : (produkt ? produkt + '-Dateien' : 'Dateien')) + '): ' + d.neuer_pfad
  ] });
}
bloecke.push({ zeilen: ['Referenz: Beleg ' + d.beleg_id] });

const n = render(bloecke);
return { json: { text: n.text, html: n.html, datei } };

// Ergebnis für den aufrufenden Ablauf (BELEG 1, BELEG 2 bzw. Ally)
const d = $('1.3 Ziel berechnen').first().json;
const db = $('1.6 Status und Klärungen aktualisieren').first().json || {};
return [{ json: {
  erledigt: true,
  test: d.test,
  beleg_id: d.beleg_id,
  ziel: d.ziel,
  pdf_verschoben: d.verschieben,
  pdf_bereich: d.neuer_bereich,
  pdf_pfad: d.neuer_pfad,
  neuer_status: db.neuer_status || null,
  geschlossene_klaerungen: db.geschlossene_klaerungen || [],
  hinweis: d.test ? 'Testlauf: nichts verschoben, nichts gespeichert, keine Nachricht.' : ''
} }];

// Verschoben? Ohne erfolgreiches Verschieben werden Status und Ablageort nicht geändert
const r = $input.item.json || {};
if (r.ok !== true) throw new Error('PDF von Beleg ' + $('1.3 Ziel berechnen').item.json.beleg_id + ' konnte nicht verschoben werden' + (r.ort ? ' (' + r.ort + ')' : '') + ': ' + (r.fehler || 'unbekannter Fehler'));
return { json: $('1.3 Ziel berechnen').item.json };

// PDF für die Nachricht holen (SPEICHER 1); die Nachricht schickt die PDF direkt in den Chat
const d = $('1.3 Ziel berechnen').item.json;
return { json: { aktion: 'holen', bereich: d.neuer_bereich || 'ally', pfad: d.neuer_pfad || '_' } };

