-- Benachrichtigung in der Oberfläche zur Chat-Nachricht (BA10, Stefan 20.10.2026), Art beleg_ablage, gleiche Person wie im Chat.
-- Wirft nie einen Fehler; die Chat-Nachricht läuft unverändert und unabhängig davon (eigener Zweig, läuft vor dem Senden).
SELECT ally_benachrichtigung_aus_chat($1::text, 'beleg_ablage', NULLIF($2::text, ''), NULL, NULL, 'BELEG 3') AS r;
